#!/bin/bash
#
# es-fork-coverage.sh — test + measure ONLY what the Enter Space fork changes.
#
# Upstream rclone runs its own full suite for every release; re-measuring it
# here would drown the fork's patches in upstream's code. So:
#
#   1. bin/es-forkcov-include.txt (generated by `bin/es-forkcov.go gen` from
#      `git diff <last merged upstream tag>..HEAD`) lists the fork-added files
#      and, for upstream files the fork modified, the functions it touched.
#   2. This script runs `go test` over every package that list names, with
#      -coverpkg spanning all of them (so a vfsbridge test that drives the
#      local backend counts toward local.go's iCloud path), and
#   3. reports covered/executable lines for the included code only, as a
#      Soren `soren-coverage:` line, failing below --floor.
#
# Hermetic: RCLONE_CONFIG points nowhere, so backend integration tests that
# need a configured remote skip; every test uses temp dirs and loopback.
#
#   bin/es-fork-coverage.sh                 # test + report
#   bin/es-fork-coverage.sh --floor 70      # …and fail below 70%
#   bin/es-fork-coverage.sh --regen         # regenerate the include list (after an upstream merge)
#
set -euo pipefail
cd "$(dirname "$0")/.."

FLOOR="${ES_FORKCOV_FLOOR:-}"
REGEN=0
while [ $# -gt 0 ]; do
    case "$1" in
        --floor) FLOOR="$2"; shift 2 ;;
        --regen) REGEN=1; shift ;;
        *) echo "unknown arg $1" >&2; exit 2 ;;
    esac
done

INCLUDE=bin/es-forkcov-include.txt
if [ "$REGEN" = 1 ] || [ ! -f "$INCLUDE" ]; then
    go run bin/es-forkcov.go gen -out "$INCLUDE"
    [ "$REGEN" = 1 ] && exit 0
fi

# Warn (don't fail) when the list is stale: HEAD moved past the recorded base merge.
base_tag=$(awk '/^# base /{print $3; exit}' "$INCLUDE")
newest=$(git tag --merged HEAD --sort=-v:refname --list 'v*' | head -1)
if [ -n "$newest" ] && [ "$newest" != "$base_tag" ]; then
    echo "WARNING: include list was generated against $base_tag but HEAD has merged $newest — run bin/es-fork-coverage.sh --regen"
fi

PKGS=$(grep -v '^#' "$INCLUDE" | awk 'NF{print $1}' | xargs -n1 dirname | sort -u | sed 's|^|./|')
COVERPKG=$(echo "$PKGS" | sed 's|^\./|github.com/rclone/rclone/|' | paste -sd, -)

WORK="$(mktemp -d "${TMPDIR:-/tmp}/es-forkcov.XXXXXX")"
trap 'rm -rf "$WORK"' EXIT
export RCLONE_CONFIG=/notfound

echo "packages:"; echo "$PKGS" | sed 's/^/  /'
set +e
# shellcheck disable=SC2086
go test -count=1 -timeout 15m -covermode=atomic -coverpkg="$COVERPKG" -coverprofile="$WORK/cover.out" $PKGS 2>&1 \
    | sed -E 's/(coverage: [0-9.]+% of statements) in .*/\1 in the fork-changed packages/' | tee "$WORK/test.log"
status=${PIPESTATUS[0]}
set -e

if [ ! -s "$WORK/cover.out" ]; then
    echo "no coverage profile written (exit $status)"
    exit "${status:-1}"
fi
ES_FORKCOV_FLOOR="$FLOOR" go run bin/es-forkcov.go report -profile "$WORK/cover.out" -include "$INCLUDE" -json || cov_status=$?
[ "$status" -ne 0 ] && exit "$status"
exit "${cov_status:-0}"
